import {ACTIONS,clamp,relationship,rand,interact,decide,log} from './engine.mjs?v=0.6.3';
import {upgradeCalendar} from './calendar.mjs?v=0.6.3';
export function initializeV6Person(p){p.bag={custom:false,weights:Object.fromEntries(Object.keys(ACTIONS).map(k=>[k,100/Object.keys(ACTIONS).length])),locked:[]};p.memoryArchive=[];p.nextMemoryId=1;p.togetherId=null;}
export function upgradeV6(s){const old=s.version!=='0.6.0';s.version='0.6.0';s.showEventId??=null;s.together||=[];s.encounters||={};s.nextTogetherId||=1;upgradeCalendar(s);for(const p of s.people){if(!p.bag)initializeV6Person(p);p.memoryArchive||=[];p.nextMemoryId||=1;if(p.action?.key==='relax'){p.action.key='sleep';p.action.recovery='pause';}if(p.priorities.relax!==undefined){const ps=[p.priorities.sleep,p.priorities.relax].filter(x=>x>0);p.priorities.sleep=ps.length?Math.min(...ps):0;delete p.priorities.relax;}if(p.actionCounts.relax){for(const key of ['started','completed','interrupted'])p.actionCounts.sleep[key]+=p.actionCounts.relax[key];delete p.actionCounts.relax;}delete p.bag.weights.relax;for(const m of p.memories){m.id||=`${p.id}-memory-${p.nextMemoryId++}`;m.created??=null;}if(old)p.bag.custom=false;}for(const a of s.activities)if(a.key==='relax')a.key='sleep';for(const r of Object.values(s.rels))r.grief||={strength:0,time:s.time,cause:null};return s;}
export function editBag(p,key,value){if(!ACTIONS[key])return;const weights=p.bag.weights,locks=new Set(p.bag.locked||[]);locks.delete(key);const held=[...locks].reduce((n,k)=>n+(weights[k]||0),0),target=clamp(Number(value)||0,0,100-held),others=Object.keys(ACTIONS).filter(k=>k!==key&&!locks.has(k)),rest=100-held-target,total=others.reduce((n,k)=>n+(weights[k]||0),0);if(!others.length){weights[key]=100-held;return;}weights[key]=target;for(const k of others)weights[k]=total?rest*(weights[k]||0)/total:rest/others.length;p.bag.custom=true;}
export function bagRows(s,p,rows,urgent){if(!p.bag?.custom)return rows;let total=0;const enriched=rows.map(r=>{const need=r.key==='sleep'?(100-p.needs.energy+100-p.needs.fun)/120:r.key==='social'?(100-p.needs.social)/80:(100-p.needs.expression)/80;const context=clamp(.5+need+r.emotion/60,.25,2.5),weight=r.blocked?0:(p.bag.weights[r.key]||0)*context*r.factor;total+=weight;return {...r,baseChance:p.bag.weights[r.key]||0,context,bagWeight:weight};});return enriched.map(r=>({...r,chance:urgent?(r.key===urgent?100:0):total?r.bagWeight/total*100:r.key==='sleep'?100:0}));}
export function coolRelation(s,r){const friendship=Math.max(0,r.affinity)/100;r.grief||={strength:0,time:s.time,cause:null};r.grief.strength=Math.max(0,r.grief.strength-.015);const floor=Math.min(15,r.grief.strength*.45);r.tension=clamp(Math.max(floor,r.tension-(.02+.18*friendship)));}
export function markGrief(s,r,event){r.grief={strength:clamp((r.grief?.strength||0)+6),time:s.time,cause:event?.text||'Accrochage'};}
export function repairGrief(r,amount=4){if(r.grief)r.grief.strength=Math.max(0,r.grief.strength-amount);}
function segmentDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,d=dx*dx+dy*dy,t=d?clamp(((p.x-a.x)*dx+(p.y-a.y)*dy)/d,0,1):0;return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);}
export function socialMinute(s,previous){s.together||=[];s.encounters||={};for(const session of s.together){if(session.ended)continue;const ps=session.members.map(id=>s.people.find(p=>p.id===id)).filter(Boolean);if(ps.length!==2||s.time>=session.until||ps.some(p=>p.engagement||p.needs.energy<15||p.action?.key!=='sleep'||p.togetherId!==session.id)){session.ended=s.time;session.reason=ps.some(p=>p.engagement)?'Engagement prioritaire':'Chacun reprend sa vie';for(const p of ps)p.togetherId=null;log(s,'social','Le moment ensemble se termine.',session.members,{explanation:session.reason});continue;}if(ps.every(p=>!p.action.route.length)&&s.time%30===0)interact(s,ps[0],ps[1]);}s.together=s.together.filter(t=>!t.ended||s.time-t.ended<1440);
for(let i=0;i<s.people.length;i++)for(let j=i+1;j<s.people.length;j++){const a=s.people[i],b=s.people[j],pa=previous.get(a.id)||a,pb=previous.get(b.id)||b,key=[a.id,b.id].sort().join('/'),row=s.encounters[key]||={near:false,next:0};const moving=a.action?.route.length||b.action?.route.length,near=moving&&(Math.min(segmentDistance(a,pb,b),segmentDistance(b,pa,a))<30);if(!near){row.near=false;continue;}if(row.near)continue;row.near=true;if(s.time<row.next||a.engagement||b.engagement||a.togetherId||b.togetherId||a.needs.energy<20||b.needs.energy<20||(a.nextEncounter||0)>s.time||(b.nextEncounter||0)>s.time)continue;row.next=s.time+120;const r=relationship(s,a,b),intensity=Math.max(Math.abs(r.affinity),r.tension);if(rand(s)>.035+intensity*.003)continue;a.nextEncounter=b.nextEncounter=s.time+30;const outcome=interact(s,a,b);a.encounterVisual=b.encounterVisual={until:s.time+20,outcome,partner:outcome==='conflict'?'#!$?':'♡'};if(outcome==='positive'&&['social','sleep'].includes(a.action?.key)&&['social','sleep'].includes(b.action?.key)&&r.affinity>20&&rand(s)<.25){const id=`together-${s.nextTogetherId++}`;for(const p of [a,b]){decide(s,p,'sleep',{recovery:'pause'});p.togetherId=id;p.action.partners=[p===a?b.id:a.id];p.action.why='Détente ensemble';}s.together.push({id,members:[a.id,b.id],created:s.time,until:s.time+180,ended:null});log(s,'social',`${a.name} et ${b.name} vont décrocher ensemble.`,[a.id,b.id]);}}
}
export function validateV6(s){for(const p of s.people){const b=p.bag;if(!b||typeof b.custom!=='boolean'||!Array.isArray(b.locked)||b.locked.some(k=>!ACTIONS[k])||Object.keys(ACTIONS).some(k=>!Number.isFinite(b.weights[k])||b.weights[k]<0||b.weights[k]>100)||Math.abs(Object.values(b.weights).reduce((a,b)=>a+b,0)-100)>.01)throw Error('Sac personnalisé invalide.');if(!Array.isArray(p.memoryArchive))throw Error('Archive de souvenirs invalide.');}if(!Array.isArray(s.together)||s.together.some(t=>!Array.isArray(t.members)||t.members.length!==2||!Number.isFinite(t.until)))throw Error('Session ensemble invalide.');}
